#!/usr/bin/env node
/*!
 * Module dependencies.
 */
var qrcode=require("../lib/main"),path=require("path"),fs=require("fs"),name=process.argv[1].replace(/^.*[\\\/]/,"").replace(".js","");
/*!
 * Parse the process name
 */
/*!
 * Parse the input
 */
if(process.stdin.isTTY){var input=process.argv[2];handleInput(input)}else{var readline=require("readline"),interface=readline.createInterface({input:process.stdin,output:process.stdout,terminal:!1});interface.on("line",function(e){handleInput(e)})}
/*!
 * Process the input
 */function handleInput(e){
/*!
     * Display help
     */
e&&"-h"!==e&&"--help"!==e||(help(),process.exit())
/*!
     * Display version
     */,"-v"!==e&&"--version"!==e||(version(),process.exit())
/*!
     * Render the QR Code
     */,qrcode.generate(e)}
/*!
 * Helper functions
 */function help(){console.log(["","Usage: "+name+" <message>","","Options:","  -h, --help           output usage information","  -v, --version        output version number","","Examples:","","  $ "+name+" hello","  $ "+name+' "hello world"',""].join("\n"))}function version(){var e=path.join(__dirname,"..","package.json"),n=JSON.parse(fs.readFileSync(e),"utf8");console.log(n.version)}